<script setup lang="ts">import {Run} from '../types/domain';import {number} from '../utils/format';defineProps<{run:Run}>();const dispersionLabel=(d:Run['result']['statistics']['dispersion'])=>d.status==='not_testable'?'无法检验':d.status==='not_recorded'?'历史未记录':'已检验';const dispersionValue=(d:Run['result']['statistics']['dispersion'])=>d.status==='testable'?number(d.R2,4):'无法检验';</script><template><div class="run-summary"><div><span class="eyebrow">{{run.result.study.code}} / AITCHISON GEOMETRY</span><h3>{{run.result.study.name}}</h3><p>{{run.result.statistics.n}}样本 · {{run.result.statistics.k}}组 · {{run.result.components.length}}成分</p></div><div><span>组间R² / 全局p</span><b>{{number(run.result.statistics.R2,4)}}</b><small>p {{number(run.result.statistics.p,4)}} / {{run.permutations}}次置换</small></div><div><span>组内离散度R² / 置换p</span><b>{{dispersionValue(run.result.statistics.dispersion)}}</b><small>{{dispersionLabel(run.result.statistics.dispersion)}}<template v-if="run.result.statistics.dispersion.status==='testable'"> · p {{number(run.result.statistics.dispersion.p,4)}}</template></small></div><div><span>显式零替换</span><b>{{run.delta}}<em> δ</em></b><small>{{run.result.zero_rows}}行含零 / 非零行仅闭合</small></div></div></template>
